    private void btnLoginActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLoginActionPerformed
        // TODO add your handling code here:
        try {
            if (username.getText().equals("")) {
                throw new Exception("Username Harus Diisi");
            } 
            else if (email.getText().equals("")) {
                throw new Exception("Email Harus Diisi");
            }
            else if (password.getText().equals("")) {
                throw new Exception("Password Harus Diisi");
            } 
            else if (!username.getText().equals("Jijul")) {
                throw new Exception("Username Salah");
            } 
            else if (!email.getText().equals("jijul@gmail.com")) {
                throw new Exception("Email Salah");
            } 
            else if (!password.getText().equals("0808")) {
                throw new Exception("Password Salah");
            } 
            else {
                JOptionPane.showMessageDialog(null, "Selamat Anda Berhasil Login", "Sukses Login", JOptionPane.INFORMATION_MESSAGE);
                new Dashboard().setVisible(true);
                this.dispose();
            }
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, e.getMessage(), "ERROR", JOptionPane.ERROR_MESSAGE);
            
            if (username.getText().equals("")) {
                username.requestFocus();
            } 
            else if (email.getText().equals("")) {
                email.requestFocus();
            } 
            else if (password.getText().equals("")) {
                password.requestFocus();
            } 
            else {
                username.setText("");
                email.setText("");
                password.setText("");
                username.requestFocus();
            }
        } finally {
            System.out.println("Proses Login Selesai Dijalankan");
        }
    }//GEN-LAST:event_btnLoginActionPerformed

    private void btnCancelActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCancelActionPerformed
        // TODO add your handling code here:
        username.setText("");
        email.setText("");
        password.setText("");

        username.requestFocus();

    }//GEN-LAST:event_btnCancelActionPerformed

